INSERT INTO kpi_catalog (code, section, name, unit, source, intake, formula, benchmark_value, benchmark_source, benchmark_basis, threshold_scored, threshold_direction, threshold_target, threshold_lo, threshold_hi, cms_fetched) VALUES ('OPS-02', 'Operations', 'Net Census Change', 'change', 'upload', 'report-guide', 'censusEnd - censusStart', 'Directional: NIC MAP senior-housing occupancy ~88.7% Q3 2025, rising ~0.5-0.7 pp/qtr for 17+ consecutive quarters (IL 90.2%, AL 87.2%). A community with net census decline while the sector rises is the red flag. Gross-decline reference: SOSH 2025 move-out/turnover (IL 44.3%, AL 48.1%, MC 64.7%, CCRC 15.6%).', 'NIC MAP Senior Housing Market Fundamentals (quarterly); SOSH 2025 Table 2.15', 'Industry — NIC MAP trend + SOSH turnover (directional)', FALSE, NULL, NULL, NULL, NULL, FALSE);
