INSERT INTO kpi_catalog (code, section, name, unit, source, intake, formula, benchmark_value, benchmark_source, benchmark_basis, threshold_scored, threshold_direction, threshold_target, threshold_lo, threshold_hi, cms_fetched) VALUES ('NURC-04', 'Nursing / Clinical', 'Facility-Acquired Pressure Injury Rate', 'rate', 'upload', 'report-guide', '(newPressureInjuries / residentDays) * 1000', 'Nursing SNF: Pressure Ulcer Incidence — national 5-6%; Stage 2+ new-onset <2% (per 1,000 resident-days basis here).', 'CMS Quality Measures; Senior Living KPI Library (Final GAPS) NURC-04', 'Industry / CMS survey', TRUE, 'lower', 2, NULL, NULL, FALSE);
