INSERT INTO kpi_catalog (code, section, name, unit, source, intake, formula, benchmark_value, benchmark_source, benchmark_basis, threshold_scored, threshold_direction, threshold_target, threshold_lo, threshold_hi, cms_fetched) VALUES ('NURC-08', 'Nursing / Clinical', 'Unplanned Hospital Transfer Rate', 'rate', 'upload', 'report-guide', '(hospitalDischarges / residentDays) * 1000', 'Distinct from NURC-07''s 30-day readmission %— this is a raw transfer-event rate per 1,000 resident-days, lower is better.', 'Senior Living KPI Library (Final GAPS) NURC-08', 'Internal — own-baseline', FALSE, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('NURC-08', 'hospitalDischarges', 'Hospital discharges/returns in period', 'count');
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('NURC-08', 'residentDays', 'Resident-days in period', 'count');
INSERT INTO kpi_catalog (code, section, name, unit, source, intake, formula, benchmark_value, benchmark_source, benchmark_basis, threshold_scored, threshold_direction, threshold_target, threshold_lo, threshold_hi, cms_fetched) VALUES ('NURC-17', 'Nursing / Clinical', 'Nursing Hours per Resident Day (HPRD)', 'rate', 'upload', 'report-guide', 'nursingHours / residentDays', 'Nursing SNF: directionally comparable to CMS Total Nursing HPRD (3.6-3.8 national avg), though this cut is nursing-department worked hours only, not the full RN+LPN+aide PBJ measure.', 'CMS staffing requirements; Senior Living KPI Library (Final GAPS) NURC-17', 'Industry / CMS survey (directional)', FALSE, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('NURC-17', 'nursingHours', 'Nursing department worked hours (regular+OT) in period', 'hours');
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('NURC-17', 'residentDays', 'Resident-days in period', 'count');
INSERT INTO kpi_catalog (code, section, name, unit, source, intake, formula, benchmark_value, benchmark_source, benchmark_basis, threshold_scored, threshold_direction, threshold_target, threshold_lo, threshold_hi, cms_fetched) VALUES ('SALM-08', 'Sales / Marketing / CRM', 'Net Move-Ins', 'change', 'upload', 'report-guide', 'moveInCount - totalMoveOuts', 'Higher is better — net of move-ins minus move-outs for the period; a positive number indicates net occupancy growth.', 'Senior Living KPI Library (Final GAPS) SALM-08', 'Internal — own-baseline', FALSE, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('SALM-08', 'moveInCount', 'Move-ins in period', 'count');
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('SALM-08', 'totalMoveOuts', 'Total move-outs', 'count');
INSERT INTO kpi_catalog (code, section, name, unit, source, intake, formula, benchmark_value, benchmark_source, benchmark_basis, threshold_scored, threshold_direction, threshold_target, threshold_lo, threshold_hi, cms_fetched) VALUES ('SALM-09', 'Sales / Marketing / CRM', 'Move-Out Rate (Attrition)', 'percent', 'upload', 'report-guide', '(totalMoveOuts / occupiedUnits) * 100', 'Sales / Revenue: Annual Turnover proxy (IL 44.3%, AL 48.1%, MC 64.7%, CCRC 15.6%, annualized) — this cut is move-outs as % of occupied units for the period.', 'SOSH 2025 (Table 2.15 — Annual Turnover); Senior Living KPI Library (Final GAPS) SALM-09', 'Industry / CMS survey (directional)', FALSE, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('SALM-09', 'totalMoveOuts', 'Total move-outs', 'count');
INSERT INTO kpi_inputs (kpi_code, input_key, label, unit) VALUES ('SALM-09', 'occupiedUnits', 'Occupied units (by care level)', 'count');
